  function supportedDistance(occ,id){const a=(ST.evidence.get(key(occ,id))||[]).map(x=>Math.min(x.castDistance,x.hitDistance)).sort((a,b)=>b-a);return a[CFG.minCastConfirmations-1]??0;}
