      if(ST.running&&W.KVPV_FAR_SCOPE?.status?.()?.kind!=='TRU_TIEN'&&(canFight()||entryGuard())&&eligible(r.c?.target)&&!towerFinish()&&!ST.ownMove){ST.blockedSteering++;return undefined;}
