 const fixedTeam=()=>typeof _Ba!=='undefined'&&!!_Ba?._cm?._q3t?.ins?.getHasTeams?.();
// [VI dòng gốc 31] Khai báo biến có thể gán lại bằng let: timer = null
 let timer=null;
