    const type=d.types.find(t=>(t.type===1||knbAllowed)&&!c.blockedTypes.includes(t.type)&&Number.isSafeInteger(t.count)&&t.count>=0&&t.count<t.limit&&Number.isFinite(t.balance)&&t.balance>=t.cost);
