  const occ=Number(prop(S.combat?.target,'occ')),candidates=rows.filter(r=>r.occ===occ&&r.id>=8001&&r.id<=8009&&r.hits>=8&&r.measuredCycles>=8&&r.hits/r.casts>=.8);
