if(a>0&&active(a)&&guide.getAwardState?.(a)===1&&!S.sent.has(gkey)&&typeof ns()?.activity_guide?._lin?.instance?.c2sGetAward==='function'){send(gkey,{kind:'guide',act:a},()=>ns().activity_guide._lin.instance.c2sGetAward(a));return;}
